import{_ as t,o as a,c as e,a4 as r}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"对 U-Boot 启动分区直接 dd 写入是极度危险的操作","description":"","frontmatter":{"title":"对 U-Boot 启动分区直接 dd 写入是极度危险的操作","date":"2026-07-18T00:00:00.000Z"},"headers":[],"relativePath":"posts/血的教训-盒子变砖.md","filePath":"posts/血的教训-盒子变砖.md"}'),l={name:"posts/血的教训-盒子变砖.md"};function d(i,o,s,n,c,_){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="对-u-boot-启动分区直接-dd-写入是极度危险的操作" tabindex="-1">对 U-Boot 启动分区直接 dd 写入是极度危险的操作 <a class="header-anchor" href="#对-u-boot-启动分区直接-dd-写入是极度危险的操作" aria-label="Permalink to &quot;对 U-Boot 启动分区直接 dd 写入是极度危险的操作&quot;">​</a></h1><h2 id="事发经过" tabindex="-1">事发经过 <a class="header-anchor" href="#事发经过" aria-label="Permalink to &quot;事发经过&quot;">​</a></h2><p>远程操作一台海思 HI3798MV100 电视盒子（Ubuntu 20.04 / ARM / 6.4G 存储）：</p><ol><li>修改 <code>/dev/mmcblk0p2</code>（bootargs 分区，即 U-Boot 环境变量存储区）</li><li>用 <code>dd</code> 直接写入修改后的数据</li><li>第一版写入 CRC 校验错误 → 盒子仍能启动（U-Boot 用默认值）</li><li>第二版写入 CRC 校验正确，但 <code>mmz=ddr,0,0,256M</code> 改为 <code>mmz=ddr,0,0,0</code> → 盒子变砖，无法启动</li></ol><h2 id="致命错误" tabindex="-1">致命错误 <a class="header-anchor" href="#致命错误" aria-label="Permalink to &quot;致命错误&quot;">​</a></h2><ol><li><strong>备份存在盒子里</strong> — 盒子砖了 = 备份也拿不到</li><li><strong>直接写分区没有硬件 recovery 方案</strong> — 没有串口线、没有 TF 卡引导方案就敢动 boot 分区</li><li><strong>不了解海思 U-Boot 实现细节</strong> — 海思 Fastboot 对 U-Boot 环境格式做了魔改</li><li><strong>没有备好恢复方案就上手</strong> — 应该先准备 TF 卡刷机卡再改 bootargs</li></ol><h2 id="恢复方案-事后总结" tabindex="-1">恢复方案（事后总结） <a class="header-anchor" href="#恢复方案-事后总结" aria-label="Permalink to &quot;恢复方案（事后总结）&quot;">​</a></h2><p>对于海思 HI3798MV100 变砖：</p><ol><li><strong>USB 烧录模式</strong> — 短接 eMMC CLK+GND（或主板背面测试点），插 USB 线连电脑，用 HiTool（Windows 工具）刷回原厂 bootargs</li><li><strong>TF 卡引导</strong> — 部分海思盒子支持复位键 + 插电从 TF 卡引导，需制作对应 bootloader 卡</li><li><strong>串口（UART）</strong> — 板载 4 针 UART 接口，用 USB-TTL 线连接能看到 U-Boot 输出，在 U-Boot 命令行恢复</li></ol><h2 id="如果再犯" tabindex="-1">如果再犯 <a class="header-anchor" href="#如果再犯" aria-label="Permalink to &quot;如果再犯&quot;">​</a></h2><p>应该用 HiTool 刷机工具通过 USB 烧录，而不是直接 dd 分区。对于嵌入式设备的启动分区，永远不要用 dd 直接写，应使用厂商提供的专用工具。</p>',11)])])}const b=t(l,[["render",d]]);export{p as __pageData,b as default};
